"use client";

import { FormEvent, useState } from "react";
import { useRouter } from "next/navigation";

export function VocabularyWordDetailsManager({ wordId, isActive, initial }: { wordId: string; isActive: boolean; initial: { lemma: string; partOfSpeech: string | null; cefrLevel: string | null; britishTranscription: string | null; americanTranscription: string | null; britishAudioUrl: string | null; americanAudioUrl: string | null } }) {
  const router = useRouter();
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [word, setWord] = useState(initial);

  async function send(url: string, body: object, method = "POST") {
    setBusy(true); setError(null);
    try {
      const response = await fetch(url, { method, headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
      const result = await response.json().catch(() => ({})) as { error?: string };
      if (!response.ok) throw new Error(result.error ?? "Request failed");
      router.refresh();
    } catch (caught) { setError(caught instanceof Error ? caught.message : "Request failed"); } finally { setBusy(false); }
  }

  function submitDetail(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const kind = String(form.get("kind"));
    const body = Object.fromEntries([...form.entries()].filter(([key]) => key !== "kind"));
    void send(`/api/admin/vocabulary/${wordId}/details`, { kind, ...body });
  }

  return <section className="mt-8 grid gap-5 lg:grid-cols-2"><form onSubmit={(event) => { event.preventDefault(); void send(`/api/admin/vocabulary/${wordId}`, word, "PATCH"); }} className="rounded-2xl border border-slate-200 bg-white p-5"><h2 className="text-xl font-bold">Edit word</h2><div className="mt-3 grid gap-3"><label className="text-sm">Lemma<input required value={word.lemma} onChange={(event) => setWord({ ...word, lemma: event.target.value })} className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2" /></label><label className="text-sm">Part of speech<select value={word.partOfSpeech ?? ""} onChange={(event) => setWord({ ...word, partOfSpeech: event.target.value || null })} className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2"><option value="">Not set</option>{["NOUN", "VERB", "ADJECTIVE", "ADVERB", "PRONOUN", "PREPOSITION", "CONJUNCTION", "DETERMINER", "NUMERAL", "INTERJECTION", "PHRASE", "PHRASAL_VERB", "IDIOM", "OTHER"].map((part) => <option key={part}>{part}</option>)}</select></label><label className="text-sm">CEFR<select value={word.cefrLevel ?? ""} onChange={(event) => setWord({ ...word, cefrLevel: event.target.value || null })} className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2"><option value="">Not set</option>{["A1", "A2", "B1", "B2", "C1", "C2"].map((level) => <option key={level}>{level}</option>)}</select></label><label className="text-sm">British audio URL<input value={word.britishAudioUrl ?? ""} onChange={(event) => setWord({ ...word, britishAudioUrl: event.target.value || null })} className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2" /></label><label className="text-sm">American audio URL<input value={word.americanAudioUrl ?? ""} onChange={(event) => setWord({ ...word, americanAudioUrl: event.target.value || null })} className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2" /></label></div><button disabled={busy} className="mt-4 rounded-lg bg-blue-700 px-3 py-2 text-sm font-semibold text-white disabled:opacity-60">Save word</button><button type="button" disabled={busy} onClick={() => void send(`/api/admin/vocabulary/${wordId}`, { isActive: !isActive }, "PATCH")} className="ml-3 text-sm font-semibold text-slate-700 underline disabled:opacity-60">{isActive ? "Deactivate" : "Activate"}</button><p className="mt-3 text-sm text-slate-600">Used words are never hard-deleted; deactivation keeps lessons and user history intact.</p></form><form onSubmit={submitDetail} className="rounded-2xl border border-slate-200 bg-white p-5"><h2 className="text-xl font-bold">Add meaning</h2><input type="hidden" name="kind" value="meaning" /><label className="mt-3 block text-sm">Definition<textarea required name="definition" className="mt-1 min-h-20 w-full rounded-lg border border-slate-300 px-3 py-2" /></label><label className="mt-3 block text-sm">Translation<input name="translation" className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2" /></label><button disabled={busy} className="mt-3 rounded-lg bg-blue-700 px-3 py-2 text-sm font-semibold text-white disabled:opacity-60">Add meaning</button></form><form onSubmit={submitDetail} className="rounded-2xl border border-slate-200 bg-white p-5"><h2 className="text-xl font-bold">Add example</h2><input type="hidden" name="kind" value="example" /><label className="mt-3 block text-sm">Sentence<textarea required name="sentence" className="mt-1 min-h-20 w-full rounded-lg border border-slate-300 px-3 py-2" /></label><label className="mt-3 block text-sm">Translation<input name="translation" className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2" /></label><button disabled={busy} className="mt-3 rounded-lg bg-blue-700 px-3 py-2 text-sm font-semibold text-white disabled:opacity-60">Add example</button></form><form onSubmit={submitDetail} className="rounded-2xl border border-slate-200 bg-white p-5"><h2 className="text-xl font-bold">Add collocation</h2><input type="hidden" name="kind" value="collocation" /><label className="mt-3 block text-sm">Collocation<input required name="value" className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2" /></label><label className="mt-3 block text-sm">Translation<input name="translation" className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2" /></label><button disabled={busy} className="mt-3 rounded-lg bg-blue-700 px-3 py-2 text-sm font-semibold text-white disabled:opacity-60">Add collocation</button></form><form onSubmit={submitDetail} className="rounded-2xl border border-slate-200 bg-white p-5 lg:col-span-2"><h2 className="text-xl font-bold">Add relation</h2><p className="mt-1 text-sm text-slate-600">Use the target word ID from its CMS page. This prevents accidental fuzzy links.</p><input type="hidden" name="kind" value="relation" /><div className="mt-3 grid gap-3 md:grid-cols-3"><label className="md:col-span-2 text-sm">Target word ID<input required name="targetWordId" className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2" /></label><label className="text-sm">Relation<select name="type" className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2"><option value="SYNONYM">Synonym</option><option value="ANTONYM">Antonym</option><option value="RELATED">Related</option><option value="PHRASAL_EQUIVALENT">Phrasal equivalent</option><option value="FORMAL_EQUIVALENT">Formal equivalent</option><option value="INFORMAL_EQUIVALENT">Informal equivalent</option><option value="BRITISH_VARIANT">British variant</option><option value="AMERICAN_VARIANT">American variant</option></select></label></div><button disabled={busy} className="mt-3 rounded-lg bg-blue-700 px-3 py-2 text-sm font-semibold text-white disabled:opacity-60">Add relation</button></form>{error ? <p role="alert" className="text-sm text-red-700 lg:col-span-2">{error}</p> : null}</section>;
}
